import os
import json
import time
import hashlib
import tempfile
import secrets
import stat
import fcntl
from pathlib import Path


class SecureSessionStore:
    """File-based session store with path traversal protection."""

    SESSION_DIR = '/var/lib/app/sessions'
    MAX_SESSION_AGE = 3600

    def __init__(self, session_dir=None):
        self._session_dir = session_dir or self.SESSION_DIR
        os.makedirs(self._session_dir, mode=0o700, exist_ok=True)

    def _validate_session_id(self, session_id: str) -> bool:
        """Strict validation: only hex characters, fixed length."""
        if not session_id:
            return False
        if len(session_id) != 64:
            return False
        try:
            int(session_id, 16)
            return True
        except ValueError:
            return False

    def _get_session_path(self, session_id: str) -> str:
        """Resolve session file path with symlink protection."""
        if not self._validate_session_id(session_id):
            raise ValueError("Invalid session ID format")

        candidate = os.path.join(self._session_dir, f"sess_{session_id}")

        # Resolve any symlinks to get the real path
        resolved = os.path.realpath(candidate)

        # Verify the resolved path is within our session directory
        real_session_dir = os.path.realpath(self._session_dir)
        if not resolved.startswith(real_session_dir + os.sep) and resolved != real_session_dir:
            raise PermissionError("Path traversal detected")

        return resolved  # Return resolved path to prevent TOCTOU

    def _safe_open_session(self, path: str, flags: int, mode: int = 0o600):
        """Open session file safely, rejecting symlinks."""
        try:
            fd = os.open(path, flags | os.O_NOFOLLOW, mode)
        except OSError as e:
            if e.errno == 40:  # ELOOP - symlink detected
                raise PermissionError("Symlink detected in session path")
            raise

        # Verify the opened file is in the correct directory
        fd_stat = os.fstat(fd)
        dir_stat = os.stat(self._session_dir)

        # Verify the file's parent directory is our session directory
        # by checking the file is a regular file
        if not stat.S_ISREG(fd_stat.st_mode):
            os.close(fd)
            raise PermissionError("Session path is not a regular file")

        return fd

    def create_session(self, user_id: str, metadata: dict = None) -> str:
        """Create a new session and return the session ID."""
        session_id = secrets.token_hex(32)
        session_data = {
            'user_id': user_id,
            'created_at': time.time(),
            'last_accessed': time.time(),
            'metadata': metadata or {},
            'csrf_token': secrets.token_hex(16)
        }

        path = self._get_session_path(session_id)

        # Write session atomically using O_NOFOLLOW
        fd = self._safe_open_session(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL)
        try:
            os.write(fd, json.dumps(session_data).encode('utf-8'))
        finally:
            os.close(fd)

        return session_id

    def read_session(self, session_id: str) -> dict:
        """Read and validate a session."""
        path = self._get_session_path(session_id)

        # Open with O_NOFOLLOW to prevent symlink attacks
        try:
            fd = self._safe_open_session(path, os.O_RDONLY)
        except (FileNotFoundError, OSError):
            return None

        try:
            # Use flock to prevent concurrent modification
            fcntl.flock(fd, fcntl.LOCK_SH)
            data = os.read(fd, 65536)
            fcntl.flock(fd, fcntl.LOCK_UN)
        finally:
            os.close(fd)

        try:
            session_data = json.loads(data.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None

        # Check expiration
        if time.time() - session_data.get('created_at', 0) > self.MAX_SESSION_AGE:
            self.destroy_session(session_id)
            return None

        # Update last accessed time atomically
        session_data['last_accessed'] = time.time()
        self._atomic_write_session(path, session_data)

        return session_data

    def _atomic_write_session(self, path: str, session_data: dict):
        """Write session data atomically using rename."""
        dir_path = os.path.dirname(path)
        tmp_fd, tmp_path = tempfile.mkstemp(dir=dir_path, prefix='.tmp_sess_')
        closed = False
        try:
            os.write(tmp_fd, json.dumps(session_data).encode('utf-8'))
            os.fchmod(tmp_fd, 0o600)
            os.close(tmp_fd)
            closed = True
            os.rename(tmp_path, path)
        except Exception:
            if not closed:
                try:
                    os.close(tmp_fd)
                except OSError:
                    pass
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def update_session(self, session_id: str, updates: dict) -> bool:
        """Update session metadata."""
        session_data = self.read_session(session_id)
        if session_data is None:
            return False

        # Merge updates into metadata
        session_data['metadata'].update(updates)
        session_data['last_accessed'] = time.time()

        path = self._get_session_path(session_id)
        self._atomic_write_session(path, session_data)

        return True

    def destroy_session(self, session_id: str) -> bool:
        """Securely destroy a session."""
        try:
            path = self._get_session_path(session_id)
            try:
                fd = self._safe_open_session(path, os.O_WRONLY)
            except (FileNotFoundError, PermissionError, OSError):
                return False

            try:
                # Overwrite before delete
                os.write(fd, b'\x00' * 4096)
                os.fsync(fd)
            finally:
                os.close(fd)

            os.unlink(path)
            return True
        except (ValueError, PermissionError, OSError):
            pass
        return False

    def cleanup_expired(self) -> int:
        """Remove expired sessions."""
        removed = 0
        try:
            for entry in os.scandir(self._session_dir):
                if entry.name.startswith('sess_') and entry.is_file(follow_symlinks=False):
                    if entry.is_symlink():
                        os.unlink(entry.path)
                        removed += 1
                        continue
                    try:
                        with open(entry.path, 'r') as f:
                            data = json.load(f)
                        if time.time() - data.get('created_at', 0) > self.MAX_SESSION_AGE:
                            os.unlink(entry.path)
                            removed += 1
                    except (json.JSONDecodeError, OSError):
                        os.unlink(entry.path)
                        removed += 1
        except OSError:
            pass
        return removed


class SessionMiddleware:
    """WSGI-like middleware for session management."""

    def __init__(self, store: SecureSessionStore):
        self._store = store

    def authenticate(self, request_headers: dict) -> dict:
        """Authenticate request using session cookie."""
        cookie = request_headers.get('Cookie', '')
        session_id = self._extract_session_id(cookie)

        if not session_id:
            return None

        return self._store.read_session(session_id)

    def _extract_session_id(self, cookie_header: str) -> str:
        """Parse session ID from cookie header."""
        for part in cookie_header.split(';'):
            part = part.strip()
            if part.startswith('session_id='):
                return part[len('session_id='):]
        return None
